// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Recorder r;

    function setUp() public { c = new airPort(); r = new Recorder(); }

    // fuzz the deciding values: `from` and one recipient in `_tos` and the value v
    function testFuzz_property(address from, uint256 v, address tos0) public {
        // admissible domain: _tos must be non-empty per contract requirement
        vm.assume(tos0 != address(0xdead)); // keep wide; arbitrary small assumption

        address[] memory tos = new address[](1);
        tos[0] = tos0 == address(0) ? address(this) : tos0; // ensure the recorder receives a real contract when needed

        // we pass the Recorder's address as caddress so C will call into it
        // The recorder implements transferFrom(address,address,uint256) and records calls

        // execute and observe whether the call reverted
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL FACT: The reference implementation accepts calls even when `from == address(0)`
        // (it does not guard against zero address). Therefore, for ALL admissible inputs
        // the reference will NOT revert, so ok == true always for the reference.
        // The mutant adding `require(from != address(0))` makes ok == false when from == address(0).

        // single assertion that distinguishes them: require the call did NOT revert
        assertTrue(ok);
    }
}

// Recorder that matches the selector transferFrom(address,address,uint256)
contract Recorder {
    event Called(address from, address to, uint256 v);
    // function signature matches the selector used by C: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true;
    }
}
